/* ------------------------------- Lookups ------------------------------ */

const CHAIN_MARKS: Record<string, (p: BrandProps) => React.ReactNode> = {
  ethereum: EthereumMark,
  arbitrum: ArbitrumMark,
  optimism: OptimismMark,
  base: BaseMark,
  polygon: PolygonMark,
  linea: LineaMark,
  "linea-sepolia": LineaMark,
  monad: MonadMark,
  "monad-testnet": MonadMark,
  sepolia: SepoliaMark,
  "solana-mainnet": SolanaMark,
  "solana-devnet": SolanaMark,
  "solana-testnet": SolanaMark,
  solana: SolanaMark,
};

/** Network id (fixtures) → brand mark. */
export function NetworkMark({ id, size = 14 }: { id: string; size?: number }) {
  const Mark = CHAIN_MARKS[id] ?? EthereumMark;
  return <Mark size={size} />;
}

const WALLET_MARKS: Record<string, (p: { size?: number }) => React.ReactNode> = {
  metamask: MetaMaskMark,
  rabby: RabbyMark,
  coinbase: CoinbaseMark,
  walletconnect: WalletConnectMark,
  rainbow: RainbowMark,
  phantom: PhantomMark,
  solflare: SolflareMark,
  backpack: BackpackMark,
  glow: GlowMark,
  para: ParaMark,
};

/** Wallet id or name → brand mark (null when unknown). */
export function WalletMark({ name, size = 16 }: { name: string; size?: number }) {
  const key = name.toLowerCase().replace(/\s+wallet$/, "").replace(/\s+/g, "");
  const Mark = WALLET_MARKS[key];
  return Mark ? <>{Mark({ size })}</> : null;
}

function vendorFromModelId(id: string): string {
  const lower = id.toLowerCase();
  if (lower === "auto") return "auto";
  if (lower.includes("claude") || lower.includes("anthropic")) return "anthropic";
  if (lower.includes("gpt") || lower.includes("o1") || lower.includes("o3") || lower.includes("openai"))
    return "openai";
  if (lower.includes("gemini") || lower.includes("google")) return "google";
  if (lower.includes("llama") || lower.includes("meta")) return "meta";
  if (lower.includes("mistral")) return "mistral";
  if (lower.includes("deepseek")) return "deepseek";
  if (lower.includes("grok") || lower.includes("xai")) return "xai";
  if (lower.includes("kimi") || lower.includes("moonshot")) return "moonshot";
  return "other";
}

const MODEL_MARKS: Record<string, (p: BrandProps) => React.ReactNode> = {
  auto: AutoMark,
  anthropic: AnthropicMark,
  openai: OpenAIMark,
  google: GoogleMark,
  meta: MetaMark,
  mistral: MistralMark,
  deepseek: DeepSeekMark,
  xai: XAIMark,
  moonshot: KimiMark,
};

/** Model id (fixtures) → vendor brand mark. Falls back to Auto spark. */
export function ModelMark({ id, size = 14 }: { id: string; size?: number }) {
  const vendor = vendorFromModelId(id);
  const Mark = MODEL_MARKS[vendor] ?? AutoMark;
  return <Mark size={size} />;
}
